	private static Config newBaseConfig() {
		return new BasicConfig(PS, minimalSchema(), baseValues());
	}

	private static Config ctxOverride(Map<String, Object> overrides) {
		return new BasicConfig(PS, minimalSchema(), overrides);
	}

	@Test
	@DisplayName("getTypeName returns PipelineLoad")
	void testGetTypeName() throws Exception {
		Config cfg = newBaseConfig();
		PipelineLoadStepClient client = new PipelineLoadStepClient(cfg, Collections.<Extension> emptyList(), Collections.emptyList(), null);
		assertEquals(PipelineLoadStepExtension.TYPE, client.getTypeName());
	}

	@Test
	@DisplayName("config(Map) returns new Pipeline client with updated config")
	void testCopyViaConfig() throws Exception {
		Config cfg = newBaseConfig();
		PipelineLoadStepClient client = new PipelineLoadStepClient(cfg, Collections.<Extension> emptyList(), null, null);

		PipelineLoadStepClient copy = client.config(Map.of("load-step-id", "pipeline-copy"));

		assertNotSame(client, copy);
		assertEquals("pipeline-copy", copy.loadStepId());
		assertEquals("base-step", client.loadStepId());
		assertEquals(PipelineLoadStepExtension.TYPE, copy.getTypeName());
	}

	@Test
	@DisplayName("append(Map) returns new client and preserves base values")
	void testAppendReturnsNewClient() throws Exception {
		Config cfg = newBaseConfig();
		PipelineLoadStepClient client = new PipelineLoadStepClient(cfg, Collections.<Extension> emptyList(), null, null);

		PipelineLoadStepClient withCtx = client.append(Map.of("load-op-type", "read"));
		assertNotSame(client, withCtx);
		assertEquals("base-step", client.loadStepId());
		assertEquals("base-step", withCtx.loadStepId());
		assertEquals(PipelineLoadStepExtension.TYPE, withCtx.getTypeName());
	}

