	@Test
	@DisplayName("init uses base item-data-size and does not override step id from contexts")
	void testInitWithContextsAndItemDataSizeVariants() {
		// Base config: numeric item-data-size via item.data.size path (accessed as item-data-size)
		Config baseNumeric = newBaseConfig();
		baseNumeric.val("item-data-size", 2048L);

		// Contexts provide their own step IDs; Pipeline client should NOT replace base step ID
		Map<String, Object> ctx0 = new HashMap<>();
		Map<String, Object> load0 = new HashMap<>();
		Map<String, Object> step0 = new HashMap<>();
		step0.put("id", "ctx-0");
		load0.put("step", step0);
		ctx0.put("load", load0);

		Map<String, Object> ctx1 = new HashMap<>();
		Map<String, Object> load1 = new HashMap<>();
		Map<String, Object> step1 = new HashMap<>();
		step1.put("id", "ctx-1");
		load1.put("step", step1);
		ctx1.put("load", load1);

		List<Config> ctxConfigs = List.of(ctxOverride(ctx0), ctxOverride(ctx1));

		PipelineLoadStepClient clientNumeric = new PipelineLoadStepClient(baseNumeric, Collections.<Extension> emptyList(), ctxConfigs, null);

		assertDoesNotThrow(clientNumeric::init);
		assertEquals("base-step", baseNumeric.stringVal("load-step-id"));

		// Base config: string item-data-size
		Config baseString = newBaseConfig();
		baseString.val("item-data-size", "3MB");
		PipelineLoadStepClient clientString = new PipelineLoadStepClient(baseString, Collections.<Extension> emptyList(), ctxConfigs, null);

		assertDoesNotThrow(clientString::init);
		assertEquals("base-step", baseString.stringVal("load-step-id"));
	}
